/**
 * In-memory Event Bus
 * Provides publish/subscribe for inter-service communication
 */

type EventCallback = (payload: any) => void;

export class EventBus {
  private subscribers: Map<string, EventCallback[]> = new Map();

  /**
   * Publish an event to all subscribers
   */
  publish(event: string, payload: any): void {
    const callbacks = this.subscribers.get(event);
    if (callbacks) {
      callbacks.forEach(callback => {
        try {
          callback(payload);
        } catch (error) {
          console.error(`Error in event subscriber for "${event}":`, error);
        }
      });
    }
  }

  /**
   * Subscribe to an event
   */
  subscribe(event: string, callback: EventCallback): void {
    if (!this.subscribers.has(event)) {
      this.subscribers.set(event, []);
    }
    this.subscribers.get(event)!.push(callback);
  }
}

// Export singleton instance
export const eventBus = new EventBus();

/**
 * User Service
 * Manages users independently
 */

export interface User {
  id: string;
  name: string;
  email: string;
}

export interface CreateUserInput {
  name: string;
  email: string;
}

export interface UpdateUserInput {
  name?: string;
  email?: string;
}

export class UserService {
  private store: Map<string, User> = new Map();
  private idCounter: number = 0;

  /**
   * Generate a unique ID
   */
  private generateId(): string {
    return `user_${++this.idCounter}`;
  }

  /**
   * List all users
   */
  listUsers(): User[] {
    return Array.from(this.store.values());
  }

  /**
   * Get user by ID
   */
  getUser(id: string): User | null {
    return this.store.get(id) || null;
  }

  /**
   * Create a new user
   */
  createUser(input: CreateUserInput): User {
    const user: User = {
      id: this.generateId(),
      name: input.name,
      email: input.email,
    };
    this.store.set(user.id, user);
    return user;
  }

  /**
   * Update a user
   */
  updateUser(id: string, input: UpdateUserInput): User | null {
    const user = this.store.get(id);
    if (!user) return null;

    const updated: User = {
      ...user,
      name: input.name ?? user.name,
      email: input.email ?? user.email,
    };
    this.store.set(id, updated);
    return updated;
  }

  /**
   * Delete a user
   */
  deleteUser(id: string): boolean {
    return this.store.delete(id);
  }
}

export const userService = new UserService();

/**
 * Project Service
 * Manages projects and their members independently
 */

export interface Project {
  id: string;
  name: string;
  description: string;
  memberIds: string[];
}

export interface CreateProjectInput {
  name: string;
  description: string;
}

export interface UpdateProjectInput {
  name?: string;
  description?: string;
}

export class ProjectService {
  private store: Map<string, Project> = new Map();
  private idCounter: number = 0;

  /**
   * Generate a unique ID
   */
  private generateId(): string {
    return `project_${++this.idCounter}`;
  }

  /**
   * List all projects
   */
  listProjects(): Project[] {
    return Array.from(this.store.values());
  }

  /**
   * Get project by ID
   */
  getProject(id: string): Project | null {
    return this.store.get(id) || null;
  }

  /**
   * Create a new project
   */
  createProject(input: CreateProjectInput): Project {
    const project: Project = {
      id: this.generateId(),
      name: input.name,
      description: input.description,
      memberIds: [],
    };
    this.store.set(project.id, project);
    return project;
  }

  /**
   * Update a project
   */
  updateProject(id: string, input: UpdateProjectInput): Project | null {
    const project = this.store.get(id);
    if (!project) return null;

    const updated: Project = {
      ...project,
      name: input.name ?? project.name,
      description: input.description ?? project.description,
    };
    this.store.set(id, updated);
    return updated;
  }

  /**
   * Delete a project
   */
  deleteProject(id: string): boolean {
    return this.store.delete(id);
  }

  /**
   * Add a member to a project
   */
  addMember(projectId: string, userId: string): Project | null {
    const project = this.store.get(projectId);
    if (!project) return null;

    if (!project.memberIds.includes(userId)) {
      project.memberIds.push(userId);
    }
    return project;
  }

  /**
   * Remove a member from a project
   */
  removeMember(projectId: string, userId: string): Project | null {
    const project = this.store.get(projectId);
    if (!project) return null;

    project.memberIds = project.memberIds.filter(id => id !== userId);
    return project;
  }
}

export const projectService = new ProjectService();

/**
 * Task Service
 * Manages tasks independently and publishes events
 */

import { eventBus } from '../event-bus';

export type TaskStatus = 'todo' | 'in-progress' | 'done';

export interface Task {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  assigneeId: string | null;
  projectId: string;
}

export interface CreateTaskInput {
  title: string;
  description: string;
  projectId: string;
}

export interface UpdateTaskInput {
  title?: string;
  description?: string;
}

export class TaskService {
  private store: Map<string, Task> = new Map();
  private idCounter: number = 0;

  /**
   * Generate a unique ID
   */
  private generateId(): string {
    return `task_${++this.idCounter}`;
  }

  /**
   * Valid status transitions
   */
  private isValidTransition(currentStatus: TaskStatus, newStatus: TaskStatus): boolean {
    const transitions: Record<TaskStatus, TaskStatus[]> = {
      'todo': ['in-progress'],
      'in-progress': ['done'],
      'done': [],
    };
    return transitions[currentStatus].includes(newStatus);
  }

  /**
   * List tasks by project
   */
  listTasksByProject(projectId: string): Task[] {
    return Array.from(this.store.values()).filter(task => task.projectId === projectId);
  }

  /**
   * Get task by ID
   */
  getTask(id: string): Task | null {
    return this.store.get(id) || null;
  }

  /**
   * Create a new task
   */
  createTask(input: CreateTaskInput): Task {
    const task: Task = {
      id: this.generateId(),
      title: input.title,
      description: input.description,
      status: 'todo',
      assigneeId: null,
      projectId: input.projectId,
    };
    this.store.set(task.id, task);
    return task;
  }

  /**
   * Update a task (title and description only)
   */
  updateTask(id: string, input: UpdateTaskInput): Task | null {
    const task = this.store.get(id);
    if (!task) return null;

    const updated: Task = {
      ...task,
      title: input.title ?? task.title,
      description: input.description ?? task.description,
    };
    this.store.set(id, updated);
    return updated;
  }

  /**
   * Delete a task
   */
  deleteTask(id: string): boolean {
    return this.store.delete(id);
  }

  /**
   * Change task status (forward-only transitions)
   */
  changeStatus(id: string, newStatus: TaskStatus): Task | null {
    const task = this.store.get(id);
    if (!task) return null;

    if (!this.isValidTransition(task.status, newStatus)) {
      return null; // Invalid transition
    }

    const oldStatus = task.status;
    task.status = newStatus;

    // Publish event
    eventBus.publish('task.statusChanged', {
      taskId: task.id,
      taskTitle: task.title,
      assigneeId: task.assigneeId,
      oldStatus,
      newStatus,
    });

    return task;
  }

  /**
   * Assign task to a user
   */
  assignTask(id: string, assigneeId: string): Task | null {
    const task = this.store.get(id);
    if (!task) return null;

    task.assigneeId = assigneeId;

    // Publish event
    eventBus.publish('task.assigned', {
      taskId: task.id,
      taskTitle: task.title,
      assigneeId,
    });

    return task;
  }
}

export const taskService = new TaskService();

